<?php declare(strict_types=1);
namespace Modules\PromptEngine\Services;
use Modules\PromptEngine\DTOs\CharacterAnalysisData; use Modules\PromptEngine\Interfaces\CharacterAnalyzerInterface;
final class CharacterAnalyzerService implements CharacterAnalyzerInterface { public function analyze(string $character): CharacterAnalysisData { $known=config('promptengine.config.character_data.'.$character,[]); $defaults=['character'=>$character,'pinyin'=>null,'vietnamese_reading'=>null,'traditional_form'=>$character,'simplified_form'=>$character,'meaning_vi'=>'Chưa có dữ liệu từ nguyên đã được kiểm chứng cho chữ này.','meaning_en'=>'Verified lexical data is not available for this character.','radical'=>null,'radical_meaning'=>null,'stroke_count'=>null,'structure'=>'unknown','character_type'=>'unknown','components'=>[],'phonetic_component'=>null,'semantic_component'=>null,'etymology'=>['scholarly'=>null,'popular_mnemonic'=>null,'note'=>'Không suy đoán khi thiếu nguồn kiểm chứng.'],'historical_origin'=>null,'historical_evolution'=>[],'ancient_usage'=>null,'modern_usage'=>null,'cultural_significance'=>[],'philosophical_symbolism'=>[],'common_vocabulary'=>[],'idioms'=>[],'classical_references'=>[]]; return new CharacterAnalysisData(array_replace($defaults,$known)); } }
